const DE = {
 "id": "csd201-cs5-non-overlap",
 "title": "Remove the fewest intervals so that the rest do not overlap — greedy by END",
 "src": "src",
 "extra": [
  "cham"
 ],
 "main": "KiemTra",
 "javaMin": 8,
 "timeoutMs": 20000,
 "loose": false,
